-- CareTech FoodData Central nutrition seed
-- Generated from fooddata_central_nutrients_wide.xlsx
-- 216 foods; 1475 non-null food/nutrient values.
-- Values are per the selected serving recorded in food_items.
--
-- Expected schema:
--   food_items(id int4 PK, name text, description text, serving_description text,
--              serving_size_g int4, disclaimer text)
--   nutrients(id int4 PK/generated, name text, symbol text, unit text)
--   food_item_nutrients(food_item_id int4, nutrient_id int4, quantity numeric,
--                       PRIMARY KEY (food_item_id, nutrient_id))
--
-- B9 uses Folate, DFE. Total Fat uses FoodData Central's
-- Total lipid (fat) value. Null spreadsheet cells are not inserted;
-- a measured 0 remains 0.

BEGIN;

-- These indexes make the seed safely rerunnable and support name-based lookup.
CREATE UNIQUE INDEX IF NOT EXISTS food_items_name_seed_uidx
  ON public.food_items (name);
CREATE UNIQUE INDEX IF NOT EXISTS nutrients_name_unit_seed_uidx
  ON public.nutrients (name, unit);

WITH source AS (
