DELETE FROM public.food_item_nutrients fin
USING public.food_items f, public.nutrients n, seeded_foods sf
WHERE fin.food_item_id = f.id
  AND fin.nutrient_id = n.id
  AND f.name = sf.name
  AND n.name IN (
    'Fatty acids, total saturated',
    'Fatty acids, total monounsaturated',
    'Fatty acids, total polyunsaturated',
    'Fatty acids, total trans'
  );

WITH source AS (
  SELECT *
  FROM jsonb_to_recordset('[{"name":"Calories","symbol":"kcal","unit":"kcal"},{"name":"Vitamin B6","symbol":"B6","unit":"mg"},{"name":"Vitamin B12","symbol":"B12","unit":"ug"},{"name":"Vitamin B9 (Folate DFE)","symbol":"B9","unit":"ug"},{"name":"Vitamin D (D2 + D3)","symbol":"D","unit":"ug"},{"name":"Vitamin E (alpha-tocopherol)","symbol":"E","unit":"mg"},{"name":"Total Fat","symbol":"FAT","unit":"g"}]'::jsonb) AS x(name text, symbol text, unit text)
)
INSERT INTO public.nutrients (name, symbol, unit)
SELECT name, symbol, unit FROM source
ON CONFLICT (name, unit) DO UPDATE SET
  symbol = EXCLUDED.symbol,
  unit = EXCLUDED.unit;

