    food_name text,
    nutrient_name text,
    unit text,
    quantity numeric
  )
), resolved AS (
  SELECT f.id AS food_item_id, n.id AS nutrient_id, s.quantity
  FROM source s
  JOIN public.food_items f ON f.name = s.food_name
  JOIN public.nutrients n ON n.name = s.nutrient_name AND n.unit = s.unit
)
INSERT INTO public.food_item_nutrients (food_item_id, nutrient_id, quantity)
SELECT food_item_id, nutrient_id, quantity FROM resolved
ON CONFLICT (food_item_id, nutrient_id) DO UPDATE SET
  quantity = EXCLUDED.quantity;

COMMIT;

